-- A small slice of content/ for tests, captured when the service was seeded.
INSERT INTO `courses` (`id`, `title`, `description`, `cover_url`, `cover_alt`, `cover_width`, `cover_height`, `published_at`, `difficulty`, `learning_path`, `authors`, `technologies`, `resources`, `signup_config`, `body`, `updated_at`) VALUES ('complete-guide-zitadel', 'Zitadel Tutorial: Self-Host Auth with Docker & K8s (2026)', 'Self-host Zitadel for auth: Docker Compose, Kubernetes, OIDC, social login, multi-tenancy. Free, hands-on tutorial with copy-paste configs.', 'https://content.rawkode.academy/courses/complete-guide-zitadel/complete-guide-zitadel.png', 'Zitadel Tutorial: Self-Host Auth with Docker and Kubernetes Course Cover', 1280, 720, 1751414400, 'intermediate', '["Set up Zitadel with Postgres (local and Kubernetes)","Integrate apps with OAuth/OIDC and SAML","Run Zitadel in production with policies and automation"]', '["rawkode"]', '[]', '[{"title":"Zitadel Documentation","description":"Official Zitadel documentation","type":"url","url":"https://zitadel.com/docs","category":"documentation"},{"title":"Zitadel GitHub Repository","description":"Source code and examples","type":"url","url":"https://github.com/zitadel/zitadel","category":"code"},{"title":"Authentication Basics","description":"Understanding OAuth2 and OpenID Connect","type":"url","url":"https://oauth.net/2/","category":"documentation"}]', '{"audienceId":"ef0f1261-4fc5-4555-a82a-13e3a294b4ee","sponsor":"Zitadel","sponsorAudienceId":"179e0ff8-77d7-4125-a2b1-f595680f9f83","allowSponsorContact":true}', '{"type":"doc","content":[{"type":"heading","attrs":{"level":2,"id":"about-this-course"},"content":[{"type":"text","text":"About this Course"}]},{"type":"paragraph","content":[{"type":"text","text":"In this course, we will explore the complete guide to Zitadel, a modern identity and access management solution. We will cover everything from the basics of setting up Zitadel to advanced features and best practices for managing identities and access in your applications."}]}]}', 1779134747000);
--> statement-breakpoint
INSERT INTO `courses` (`id`, `title`, `description`, `cover_url`, `cover_alt`, `cover_width`, `cover_height`, `published_at`, `difficulty`, `learning_path`, `authors`, `technologies`, `resources`, `signup_config`, `body`, `updated_at`) VALUES ('graphql-federation-wundergraph-cosmo', 'GraphQL Federation with WunderGraph Cosmo', 'Learn how to build and scale distributed GraphQL architectures using WunderGraph Cosmo.
This comprehensive course covers federation concepts, schema design, performance optimization,
and production deployment strategies for building enterprise-grade GraphQL APIs.
', 'https://content.rawkode.academy/courses/graphql-federation-wundergraph-cosmo/graphql-federation-wundergraph-cosmo.png', 'GraphQL Federation with WunderGraph Cosmo Course Cover', 1280, 720, 1753315200, 'advanced', '["Learn federation concepts and schema design","Build and compose subgraphs with Cosmo","Optimize, observe, and deploy to production"]', '["rawkode"]', '[]', '[{"title":"WunderGraph Cosmo Documentation","description":"Official WunderGraph Cosmo documentation","type":"url","url":"https://cosmo-docs.wundergraph.com/","category":"documentation"},{"title":"GraphQL Federation Specification","description":"Apollo Federation specification and concepts","type":"url","url":"https://www.apollographql.com/docs/federation/","category":"documentation"},{"title":"WunderGraph GitHub Repository","description":"Source code and examples for WunderGraph","type":"url","url":"https://github.com/wundergraph/wundergraph","category":"code"},{"title":"Cosmo Examples","description":"Example projects using WunderGraph Cosmo","type":"url","url":"https://github.com/wundergraph/cosmo/tree/main/examples","category":"code"}]', '{"audienceId":"6f77a8d7-77d5-433c-aacb-21392e3f2c9f","sponsor":"WunderGraph","sponsorAudienceId":"eae7901e-18dd-4c19-a7d5-b038688595f5","allowSponsorContact":true}', '{"type":"doc","content":[{"type":"heading","attrs":{"level":2,"id":"about-this-course"},"content":[{"type":"text","text":"About this Course"}]},{"type":"paragraph","content":[{"type":"text","text":"GraphQL Federation has become the de facto standard for building scalable, distributed GraphQL architectures. In this advanced course, we''ll explore how to leverage WunderGraph Cosmo to build, deploy, and manage federated GraphQL services at scale."}]},{"type":"paragraph","content":[{"type":"text","text":"You''ll learn how to:"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Design and implement federated GraphQL schemas"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Build and compose multiple GraphQL subgraphs"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Handle authentication and authorization across federated services"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Optimize performance with caching and query planning"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Monitor and debug distributed GraphQL systems"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Deploy and scale federated architectures in production"}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"Whether you''re migrating from a monolithic GraphQL API or building a new distributed system from scratch, this course will provide you with the knowledge and practical skills needed to succeed with GraphQL Federation using WunderGraph Cosmo."}]}]}', 1766435435000);
--> statement-breakpoint
INSERT INTO `courses` (`id`, `title`, `description`, `cover_url`, `cover_alt`, `cover_width`, `cover_height`, `published_at`, `difficulty`, `learning_path`, `authors`, `technologies`, `resources`, `signup_config`, `body`, `updated_at`) VALUES ('teleport-for-kubernetes', 'Teleport for Kubernetes', 'Learn to deploy, configure, and operate Teleport as the access layer for your Kubernetes clusters.
From zero to a fully working setup with identity-based access, role-based controls, just-in-time
privilege escalation, and full audit logging.
', 'https://content.rawkode.academy/courses/teleport-for-kubernetes/teleport-for-kubernetes.png', 'Teleport for Kubernetes Course Cover', 1376, 768, 1774224000, 'intermediate', '["Deploy Teleport on Kubernetes with Helm","Configure identity-based access with GitHub SSO","Implement fine-grained RBAC with defense in depth","Set up just-in-time access requests for incidents","Use audit logging and session recording"]', '["rawkode"]', '["teleport","kubernetes"]', '[{"title":"Teleport Documentation","description":"Official Teleport documentation","type":"url","url":"https://goteleport.com/docs/","category":"documentation"},{"title":"Teleport GitHub Repository","description":"Source code and community edition","type":"url","url":"https://github.com/gravitational/teleport","category":"code"}]', '{"audienceId":"teleport-for-kubernetes","sponsor":"Teleport","sponsorAudienceId":"teleport","allowSponsorContact":true}', '{"type":"doc","content":[{"type":"heading","attrs":{"level":2,"id":"about-this-course"},"content":[{"type":"text","text":"About this Course"}]},{"type":"paragraph","content":[{"type":"text","text":"Kubernetes access is broken by default. Long-lived kubeconfig credentials, shared identities, no revocation, and audit logs that can''t tell you who did what. This course fixes that."}]},{"type":"paragraph","content":[{"type":"text","text":"Over six hands-on videos, you''ll deploy Teleport on Kubernetes from scratch using Helm, wire up GitHub SSO for identity-based authentication, build a two-layer RBAC model with defense in depth, implement just-in-time access requests for incident response, and explore Teleport''s audit logging and session recording capabilities."}]},{"type":"paragraph","content":[{"type":"text","text":"Everything is built on the Teleport Community Edition, which is free and open source. The video walkthroughs demonstrate the setup on a local Kind cluster — no cloud account required."}]},{"type":"paragraph","content":[{"type":"text","text":"By the end of this course, you''ll have the foundations for securing your Kubernetes access with real identities, least privilege, time-bounded elevation, and a complete audit trail."}]}]}', 1790105224000);
--> statement-breakpoint
INSERT INTO `course_modules` (`id`, `course_id`, `slug`, `frontmatter_slug`, `title`, `description`, `cover_url`, `cover_alt`, `cover_width`, `cover_height`, `section`, `sort_order`, `video`, `duration`, `difficulty`, `published_at`, `draft`, `authors`, `resources`, `body`, `updated_at`) VALUES ('complete-guide-zitadel/01-introduction', 'complete-guide-zitadel', '01-introduction', 'introduction', 'Introduction', 'Learn Zitadel: Open Source Authentication That Doesn''t Suck | Stop Paying Thousands for Identity Management
', NULL, NULL, NULL, NULL, 'Getting Started', 1, '{"id":"hgg3yhgkk4jn9l7ryjw9ebs8","thumbnailUrl":"https://content.rawkode.academy/videos/hgg3yhgkk4jn9l7ryjw9ebs8/thumbnail.jpg"}', NULL, NULL, 1751414400, 0, '["rawkode"]', '[{"title":"Zitadel Documentation","description":"Official Zitadel documentation","type":"url","url":"https://zitadel.com/docs","category":"documentation"},{"title":"Zitadel GitHub Repository","description":"Source code and examples","type":"url","url":"https://github.com/zitadel/zitadel","category":"code"},{"title":"Authentication Basics","description":"Understanding OAuth2 and OpenID Connect","type":"url","url":"https://oauth.net/2/","category":"documentation"},{"title":"OAuth PKCE Interactive Demo","description":"Try the OAuth PKCE flow right in your browser - Enter your Zitadel instance URL and client ID to test authentication","type":"embed","embedConfig":{"container":"webcontainer","src":"oauth-pkce-app","height":"800px","width":"100%","import":{"localDir":"complete-guide-zitadel/oauth-pkce-app"},"startCommand":"bun run dev"},"category":"code"}]', '{"type":"doc","content":[{"type":"heading","attrs":{"level":2,"id":"welcome-to-the-complete-guide-to-zitadel"},"content":[{"type":"text","text":"Welcome to the Complete Guide to Zitadel"}]},{"type":"paragraph","content":[{"type":"text","text":"Sick of building authentication from scratch or getting nickeled and dimed by expensive identity providers? This practical Zitadel course shows you how to implement enterprise-grade authentication without the enterprise price tag. Learn to set up and integrate Zitadel - the open source identity and access management platform written in Go - with your applications. Covers OAuth, SAML, user management, multi-tenancy, custom branding, user flows, and production deployment. No theory dumps, just hands-on implementation from David Flanagan at Rawkode Academy, who actually uses Zitadel in production. Perfect for developers and sysadmins who want authentication that works without breaking budgets or sanity."}]}]}', 1790105224000);
--> statement-breakpoint
INSERT INTO `course_modules` (`id`, `course_id`, `slug`, `frontmatter_slug`, `title`, `description`, `cover_url`, `cover_alt`, `cover_width`, `cover_height`, `section`, `sort_order`, `video`, `duration`, `difficulty`, `published_at`, `draft`, `authors`, `resources`, `body`, `updated_at`) VALUES ('complete-guide-zitadel/08-remix-integration', 'complete-guide-zitadel', '08-remix-integration', 'Remix-integration', 'Integrating with an Remix Application', 'Learn how to integrate Zitadel with an Remix application, configure authentication, and manage user sessions. We''ll cover the PKCE flow, token introspection, and adding user roles.', NULL, NULL, NULL, NULL, 'Integrating with Your Applications', 8, NULL, NULL, NULL, 1752710400, 1, '["rawkode"]', NULL, '{"type":"doc","content":[{"type":"paragraph"}]}', 1764608082000);
--> statement-breakpoint
INSERT INTO `course_modules` (`id`, `course_id`, `slug`, `frontmatter_slug`, `title`, `description`, `cover_url`, `cover_alt`, `cover_width`, `cover_height`, `section`, `sort_order`, `video`, `duration`, `difficulty`, `published_at`, `draft`, `authors`, `resources`, `body`, `updated_at`) VALUES ('complete-guide-zitadel/09-authentication-methods', 'complete-guide-zitadel', '09-authentication-methods', 'authentication-methods', 'Passwords, Passkeys, and MFA', 'Configure password policies, implement passwordless authentication with passkeys, and set up multi-factor authentication', NULL, NULL, NULL, NULL, 'Authentication', 9, '{"id":"pxdgreblk59hxyny139a7i8i","thumbnailUrl":"https://content.rawkode.academy/videos/pxdgreblk59hxyny139a7i8i/thumbnail.jpg"}', NULL, NULL, 1753833600, 0, '["rawkode"]', '[{"title":"Zitadel Authentication Methods","description":"Official documentation on authentication methods","type":"url","url":"https://zitadel.com/docs/guides/authentication","category":"documentation"},{"title":"WebAuthn & Passkeys Guide","description":"Understanding passwordless authentication","type":"url","url":"https://webauthn.guide/","category":"documentation"},{"title":"FIDO Alliance","description":"Standards for passwordless authentication","type":"url","url":"https://fidoalliance.org/","category":"documentation"}]', '{"type":"doc","content":[{"type":"heading","attrs":{"level":2,"id":"multiple-authentication-methods-in-zitadel"},"content":[{"type":"text","text":"Multiple Authentication Methods in Zitadel"}]},{"type":"paragraph","content":[{"type":"text","text":"In this video, we''re going to take a look at something very simple, but also important: allowing people to register and login to your application using Zitadel with multiple methods. We''ll cover username and password authentication, Passkeys, and explore the other options available in the Zitadel console."}]},{"type":"heading","attrs":{"level":2,"id":"getting-started-with-identity-providers"},"content":[{"type":"text","text":"Getting Started with Identity Providers"}]},{"type":"paragraph","content":[{"type":"text","text":"When you first open your Zitadel Cloud console, you''ll find the default settings for your instance. If you click on "},{"type":"text","text":"Identity Providers","marks":[{"type":"bold"}]},{"type":"text","text":", you''ll see that there are no third-party setups initially - no Google, GitHub, or other providers configured yet."}]},{"type":"paragraph","content":[{"type":"text","text":"For third-party providers like GitHub, you can click on them to get the configuration details where you''ll need to add your client ID and secret. This setup is especially important when running your own Zitadel instance, as it''s often crucial to piggyback onto existing authentication providers. We''ll be covering social login providers in detail in the next video."}]},{"type":"heading","attrs":{"level":2,"id":"configuring-password-authentication"},"content":[{"type":"text","text":"Configuring Password Authentication"}]},{"type":"paragraph","content":[{"type":"text","text":"Let''s start with the basics: how can we allow people to log in with their username and password? And even better, can we enable passwordless Passkey-based login?"}]},{"type":"paragraph","content":[{"type":"text","text":"Good news: by default, passwordless login is enabled and supports:"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Fingerprint authentication"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Security keys"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Face ID"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Other biometric methods"}]}]}]},{"type":"aside","attrs":{"variant":"warning"},"content":[{"type":"paragraph","content":[{"type":"text","text":"Important:","marks":[{"type":"bold"}]},{"type":"text","text":" Username and password authentication is NOT enabled by default in new Zitadel instances. You''ll need to manually enable this in your settings."}]}]},{"type":"heading","attrs":{"level":3,"id":"enabling-username-and-password-login"},"content":[{"type":"text","text":"Enabling Username and Password Login"}]},{"type":"paragraph","content":[{"type":"text","text":"To enable traditional password-based authentication:"}]},{"type":"orderedList","attrs":{"start":1,"type":null},"content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Navigate to your instance''s default settings"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Find the "},{"type":"text","text":"Login Behavior and Security","marks":[{"type":"bold"}]},{"type":"text","text":" section"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Enable "},{"type":"text","text":"Username and Password","marks":[{"type":"bold"}]},{"type":"text","text":" authentication"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Check that "},{"type":"text","text":"User Registration","marks":[{"type":"bold"}]},{"type":"text","text":" is allowed"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Click "},{"type":"text","text":"Save","marks":[{"type":"bold"}]}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"You''ll also find configuration options for:"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Password complexity requirements"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Password lifetime policies"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Secret rotation settings"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Login and registration restrictions"}]}]}]},{"type":"heading","attrs":{"level":2,"id":"understanding-organization-vs-instance-settings"},"content":[{"type":"text","text":"Understanding Organization vs Instance Settings"}]},{"type":"paragraph","content":[{"type":"text","text":"One crucial point that often trips up new users: Zitadel has a hierarchy of settings."}]},{"type":"aside","attrs":{"variant":"info"},"content":[{"type":"paragraph","content":[{"type":"text","text":"There are "},{"type":"text","text":"default instance-wide settings","marks":[{"type":"bold"}]},{"type":"text","text":" that apply to all organizations when they have nothing set themselves or when they inherit from the instance. Each organization can also be configured independently with its own settings."}]}]},{"type":"paragraph","content":[{"type":"text","text":"For example, if you disable user registration at the instance level but it''s still enabled at the organization level, users can still register. Always check both levels when configuring authentication:"}]},{"type":"orderedList","attrs":{"start":1,"type":null},"content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Instance Settings","marks":[{"type":"bold"}]},{"type":"text","text":": Default settings for your entire Zitadel instance"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Organization Settings","marks":[{"type":"bold"}]},{"type":"text","text":": Can override instance defaults for specific organizations"}]}]}]},{"type":"heading","attrs":{"level":2,"id":"user-registration-flow"},"content":[{"type":"text","text":"User Registration Flow"}]},{"type":"paragraph","content":[{"type":"text","text":"With registration enabled, here''s the typical user flow:"}]},{"type":"orderedList","attrs":{"start":1,"type":null},"content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"User navigates to the login page"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Clicks "},{"type":"text","text":"Register","marks":[{"type":"bold"}]},{"type":"text","text":" to create a new account"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Fills in the registration form:"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Name"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Email address"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Password (if password authentication is enabled)"}]}]}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Confirms email address via verification code"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Optionally sets up second factor authentication"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Gains access to their user profile"}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"The entire process is handled by Zitadel''s built-in UI - you don''t need to build any custom forms initially."}]},{"type":"heading","attrs":{"level":2,"id":"adding-passwordless-authentication"},"content":[{"type":"text","text":"Adding Passwordless Authentication"}]},{"type":"paragraph","content":[{"type":"text","text":"Once a user has registered, they can add passwordless authentication methods:"}]},{"type":"heading","attrs":{"level":3,"id":"setting-up-a-passkey"},"content":[{"type":"text","text":"Setting Up a Passkey"}]},{"type":"orderedList","attrs":{"start":1,"type":null},"content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Navigate to "},{"type":"text","text":"Password and Security","marks":[{"type":"bold"}]},{"type":"text","text":" in the user profile"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Click "},{"type":"text","text":"Add Method","marks":[{"type":"bold"}]}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Choose "},{"type":"text","text":"Use my own device","marks":[{"type":"bold"}]}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Give the Passkey a descriptive name"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Follow your browser/device prompts to create the Passkey"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"The Passkey can be stored in:"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Your device''s secure enclave"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Password managers like 1Password or Bitwarden"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Hardware security keys"}]}]}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"After setting up a Passkey, users can log in without entering a password - they''ll just need to authenticate with their biometric or security key."}]},{"type":"heading","attrs":{"level":2,"id":"multi-factor-authentication-mfa"},"content":[{"type":"text","text":"Multi-Factor Authentication (MFA)"}]},{"type":"paragraph","content":[{"type":"text","text":"Zitadel supports multiple second factors for enhanced security:"}]},{"type":"heading","attrs":{"level":3,"id":"totp-time-based-one-time-passwords"},"content":[{"type":"text","text":"TOTP (Time-based One-Time Passwords)"}]},{"type":"paragraph","content":[{"type":"text","text":"Users can scan a QR code with authenticator apps like:"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Google Authenticator"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Microsoft Authenticator"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"1Password"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Authy"}]}]}]},{"type":"heading","attrs":{"level":3,"id":"fido2webauthn-keys"},"content":[{"type":"text","text":"FIDO2/WebAuthn Keys"}]},{"type":"paragraph","content":[{"type":"text","text":"Hardware security keys provide the strongest second factor:"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"YubiKey"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Google Titan"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Any FIDO2-compliant key"}]}]}]},{"type":"heading","attrs":{"level":2,"id":"login-v2-and-custom-authentication-ui"},"content":[{"type":"text","text":"Login V2 and Custom Authentication UI"}]},{"type":"paragraph","content":[{"type":"text","text":"While Zitadel provides a complete authentication UI out of the box, you might want something more integrated with your application. That''s where Login V2 comes in."}]},{"type":"aside","attrs":{"variant":"tip"},"content":[{"type":"paragraph","content":[{"type":"text","text":"Login V2 hooks into the Zitadel Session API, allowing you to build custom authentication flows while still leveraging Zitadel''s security features."}]}]},{"type":"paragraph","content":[{"type":"text","text":"To enable Login V2:"}]},{"type":"orderedList","attrs":{"start":1,"type":null},"content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Go to "},{"type":"text","text":"Default Settings","marks":[{"type":"bold"}]}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Navigate to "},{"type":"text","text":"Features","marks":[{"type":"bold"}]}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Scroll down to find "},{"type":"text","text":"Login V2","marks":[{"type":"bold"}]}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Enable the feature"}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"You can then either:"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Fork Zitadel''s TypeScript reference implementation"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Build your own implementation using the Session API directly"}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"We''ll cover Login V2 in detail in an upcoming video, as there''s a lot to explore with custom authentication flows."}]},{"type":"heading","attrs":{"level":2,"id":"best-practices"},"content":[{"type":"text","text":"Best Practices"}]},{"type":"heading","attrs":{"level":3,"id":"for-development"},"content":[{"type":"text","text":"For Development"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Start with username/password for simplicity"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Enable all authentication methods to test integration"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Use Zitadel''s default UI to prototype quickly"}]}]}]},{"type":"heading","attrs":{"level":3,"id":"for-production"},"content":[{"type":"text","text":"For Production"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Enable Passkeys for better user experience"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Require MFA for sensitive applications"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Consider disabling password authentication entirely for maximum security"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Implement proper password policies if passwords are required"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Use organization-specific settings for multi-tenant applications"}]}]}]},{"type":"heading","attrs":{"level":2,"id":"whats-next"},"content":[{"type":"text","text":"What''s Next?"}]},{"type":"paragraph","content":[{"type":"text","text":"In the next video, we''ll take a look at configuring third-party OAuth providers like GitHub and Google for social login. This allows users to authenticate with accounts they already have, reducing friction in the registration process."}]},{"type":"paragraph","content":[{"type":"text","text":"After that, we''ll dive deep into Login V2 and building custom authentication experiences that seamlessly integrate with your application''s design."}]},{"type":"heading","attrs":{"level":2,"id":"summary"},"content":[{"type":"text","text":"Summary"}]},{"type":"paragraph","content":[{"type":"text","text":"Zitadel provides flexible authentication options out of the box:"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Traditional username and password"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Modern passwordless authentication with Passkeys"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Multi-factor authentication with TOTP and hardware keys"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Customizable registration and login flows"}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"The key is understanding the settings hierarchy (instance vs organization) and choosing the right authentication methods for your use case. Start simple with the defaults, then customize as your requirements evolve."}]}]}', 1764608082000);
--> statement-breakpoint
INSERT INTO `course_modules` (`id`, `course_id`, `slug`, `frontmatter_slug`, `title`, `description`, `cover_url`, `cover_alt`, `cover_width`, `cover_height`, `section`, `sort_order`, `video`, `duration`, `difficulty`, `published_at`, `draft`, `authors`, `resources`, `body`, `updated_at`) VALUES ('complete-guide-zitadel/branding-customization', 'complete-guide-zitadel', 'branding-customization', 'branding-customization', 'Branding and Customizing the Login Experience', 'Customize Zitadel''s login UI with your brand, create custom themes, modify email templates, and build white-label experiences', NULL, NULL, NULL, NULL, 'Customization', 99, NULL, NULL, NULL, 1752105600, 1, '["rawkode"]', NULL, '{"type":"doc","content":[{"type":"paragraph"}]}', 1764608082000);
