INSERT INTO `course_modules` (`id`, `course_id`, `slug`, `frontmatter_slug`, `title`, `description`, `cover_url`, `cover_alt`, `cover_width`, `cover_height`, `section`, `sort_order`, `video`, `duration`, `difficulty`, `published_at`, `draft`, `authors`, `resources`, `body`, `updated_at`) VALUES ('complete-guide-zitadel/enterprise-sso', 'complete-guide-zitadel', 'enterprise-sso', 'enterprise-sso', 'Enterprise SSO with SAML and OIDC', 'Implement enterprise single sign-on using SAML 2.0 and OpenID Connect, integrate with corporate identity providers', NULL, NULL, NULL, NULL, 'Enterprise', 99, NULL, NULL, NULL, 1752105600, 1, '["rawkode"]', NULL, '{"type":"doc","content":[{"type":"paragraph"}]}', 1764608082000);
