INSERT INTO `course_modules` (`id`, `course_id`, `slug`, `frontmatter_slug`, `title`, `description`, `cover_url`, `cover_alt`, `cover_width`, `cover_height`, `section`, `sort_order`, `video`, `duration`, `difficulty`, `published_at`, `draft`, `authors`, `resources`, `body`, `updated_at`) VALUES ('teleport-for-kubernetes/02-deploying-teleport-cluster', 'teleport-for-kubernetes', '02-deploying-teleport-cluster', 'deploying-teleport-cluster', 'Deploying a Teleport Cluster on Kubernetes', 'Deploy a working Teleport cluster on Kubernetes using Helm, with TLS certificates via cert-manager and an admin user ready to log in.
', NULL, NULL, NULL, NULL, 'Getting Started', 2, '{"id":"bx2e90jd6p1u2pkvgj1wo6b7","thumbnailUrl":"https://content.rawkode.academy/videos/bx2e90jd6p1u2pkvgj1wo6b7/thumbnail.webp"}', NULL, NULL, 1774224000, 0, '["rawkode"]', '[{"title":"Teleport Helm Chart Documentation","description":"Official Teleport Helm chart installation guide","type":"url","url":"https://goteleport.com/docs/deploy-a-cluster/helm-deployments/","category":"documentation"}]', '{"type":"doc","content":[{"type":"heading","attrs":{"level":2,"id":"getting-hands-on"},"content":[{"type":"text","text":"Getting Hands On"}]},{"type":"paragraph","content":[{"type":"text","text":"Time to get our hands on the keyboard and actually deploy our first Teleport cluster. By the end of this video, you will have a working Teleport cluster running on Kubernetes with TLS certificates and an admin user ready to log in."}]},{"type":"heading","attrs":{"level":2,"id":"prerequisites"},"content":[{"type":"text","text":"Prerequisites"}]},{"type":"paragraph","content":[{"type":"text","text":"You''ll need Kind (Kubernetes in Docker), Helm, and kubectl. No cloud account required — everything runs locally. The only dependency is cert-manager, which is just one "},{"type":"text","text":"helm install","marks":[{"type":"code"}]},{"type":"text","text":" away."}]},{"type":"heading","attrs":{"level":2,"id":"deployment-steps"},"content":[{"type":"text","text":"Deployment Steps"}]},{"type":"paragraph","content":[{"type":"text","text":"The video walks through these deployment steps:"}]},{"type":"orderedList","attrs":{"start":1,"type":null},"content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Check prerequisites","marks":[{"type":"bold"}]},{"type":"text","text":" — Verify Kind, Helm, and kubectl are installed"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Create a Kind cluster","marks":[{"type":"bold"}]},{"type":"text","text":" — A simple single control-plane configuration"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Deploy cert-manager","marks":[{"type":"bold"}]},{"type":"text","text":" — Add the Jetstack Helm repository, install cert-manager with CRDs, create a self-signed issuer and root certificate"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Configure Teleport values","marks":[{"type":"bold"}]},{"type":"text","text":" — Standalone chart mode, Multiplex proxy listener, and cert-manager integration"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Helm install","marks":[{"type":"bold"}]},{"type":"text","text":" — Use "},{"type":"text","text":"envsubst","marks":[{"type":"code"}]},{"type":"text","text":" for values templating, then "},{"type":"text","text":"helm upgrade --install","marks":[{"type":"code"}]}]}]}]},{"type":"heading","attrs":{"level":2,"id":"production-comparison"},"content":[{"type":"text","text":"Production Comparison"}]},{"type":"paragraph","content":[{"type":"text","text":"We also take a look at a real production deployment running on rawkode.cloud using Flux CD, with ACME-managed TLS certificates, Mayastor storage, and Gateway API via Cilium. The production setup isn''t that dissimilar from the local Kind deployment — just a few tweaks for your specific infrastructure."}]}]}', 1790105224000);
--> statement-breakpoint
INSERT INTO `course_modules` (`id`, `course_id`, `slug`, `frontmatter_slug`, `title`, `description`, `cover_url`, `cover_alt`, `cover_width`, `cover_height`, `section`, `sort_order`, `video`, `duration`, `difficulty`, `published_at`, `draft`, `authors`, `resources`, `body`, `updated_at`) VALUES ('teleport-for-kubernetes/01-introduction', 'teleport-for-kubernetes', '01-introduction', 'introduction', 'Introduction to Teleport for Kubernetes', 'Understand the problem with default Kubernetes access — long-lived credentials, no revocation, and audit gaps — and how Teleport solves it with short-lived certificates, real identities, and full audit logging.
', NULL, NULL, NULL, NULL, 'Getting Started', 1, '{"id":"qhc6jajwhi2ul563ncovdrg9","thumbnailUrl":"https://content.rawkode.academy/videos/qhc6jajwhi2ul563ncovdrg9/thumbnail.webp"}', NULL, NULL, 1774224000, 0, '["rawkode"]', '[{"title":"Teleport Documentation","description":"Official Teleport documentation","type":"url","url":"https://goteleport.com/docs/","category":"documentation"},{"title":"Teleport GitHub Repository","description":"Source code and community edition","type":"url","url":"https://github.com/gravitational/teleport","category":"code"}]', '{"type":"doc","content":[{"type":"heading","attrs":{"level":2,"id":"welcome-to-teleport-for-kubernetes"},"content":[{"type":"text","text":"Welcome to Teleport for Kubernetes"}]},{"type":"paragraph","content":[{"type":"text","text":"Over the next six videos, we go from zero to a fully working setup — identity-based access, role-based controls, just-in-time privilege escalation, and full audit logging. Everything you need to lock down Kubernetes access the right way."}]},{"type":"heading","attrs":{"level":2,"id":"the-problem"},"content":[{"type":"text","text":"The Problem"}]},{"type":"paragraph","content":[{"type":"text","text":"If you''ve been working with Kubernetes, you''re familiar with kubeconfig files. The standard way to authenticate with any Kubernetes cluster — you get the file, drop it into "},{"type":"text","text":"~/.kube/config","marks":[{"type":"code"}]},{"type":"text","text":", and off you go. But have you ever looked inside a kubeconfig file?"}]},{"type":"paragraph","content":[{"type":"text","text":"Typically, your kubeconfig contains a long-lived secret. These certificates live for months or years with no ability to revoke them unless you rotate the entire certificate authority of your cluster. The subject is always generic — "},{"type":"text","text":"kubernetes-admin","marks":[{"type":"code"}]},{"type":"text","text":" — because Kubernetes has no real concept of users."}]},{"type":"paragraph","content":[{"type":"text","text":"This creates audit gaps: when everyone shares the same identity, it''s hard to tell who did what. And in our AI landscape, your AI agents potentially have access to all of your clusters with the same permissions you have."}]},{"type":"heading","attrs":{"level":2,"id":"the-solution-teleport"},"content":[{"type":"text","text":"The Solution: Teleport"}]},{"type":"paragraph","content":[{"type":"text","text":"Teleport is an infrastructure access platform that sits in front of your Kubernetes clusters, SSH servers, databases, and web applications. It provides a single unified layer for authentication and authorization with complete audit capabilities."}]},{"type":"paragraph","content":[{"type":"text","text":"Instead of handing out long-lived credentials, Teleport acts as your certificate authority. When you authenticate through your company''s SSO — Okta, Google Workspace, or GitHub — Teleport issues you a short-lived x509 certificate containing your real identity, roles, and an expiration time. By default, certificates are valid for around 12 hours."}]},{"type":"heading","attrs":{"level":2,"id":"how-teleport-works"},"content":[{"type":"text","text":"How Teleport Works"}]},{"type":"paragraph","content":[{"type":"text","text":"Under the hood, there are three core services:"}]},{"type":"orderedList","attrs":{"start":1,"type":null},"content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Auth Service","marks":[{"type":"bold"}]},{"type":"text","text":" — The brain of Teleport. It runs a certificate authority, stores cluster state, users, roles, connectors, and writes to the audit log."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Proxy Service","marks":[{"type":"bold"}]},{"type":"text","text":" — Your public-facing gateway. It handles protocol detection and routing — the same port can serve the web UI, SSH connections, Kubernetes API requests, and database connections through Multiplex Mode."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Kubernetes Service","marks":[{"type":"bold"}]},{"type":"text","text":" — The agent that connects Teleport to your Kubernetes cluster''s API server. It maintains a reverse tunnel back to the proxy, meaning your API server never needs to be exposed to the internet."}]}]}]},{"type":"heading","attrs":{"level":2,"id":"whats-ahead"},"content":[{"type":"text","text":"What''s Ahead"}]},{"type":"paragraph","content":[{"type":"text","text":"In this course, we''ll walk through deploying Teleport with Helm, setting up GitHub SSO, building fine-grained RBAC with defense in depth, implementing just-in-time access requests, and exploring audit logging and session recording."}]}]}', 1790105224000);
--> statement-breakpoint
INSERT INTO `learning_paths` (`id`, `title`, `description`, `difficulty`, `estimated_duration`, `prerequisites`, `technologies`, `published_at`, `authors`, `body`, `updated_at`) VALUES ('gitops-landscape', 'GitOps Landscape', 'Build a GitOps-first operating model. This path layers modern packaging, reconciliation, and developer experience tooling—Timoni, Kluctl, FluxCD, Gimlet, and Sveltos—so you can run fleets with confidence.', 'advanced', 432, '["Comfortable with Kubernetes fundamentals (control plane, nodes, pods, services, deployments).","Daily kubectl user familiar with contexts, namespaces, and auth.","Experience managing manifests with Helm/Kustomize or similar tooling.","Working knowledge of Git workflows (branches, PRs) and CI/CD automation.","Optional: exposure to CUE, GitOps controllers (Flux/Argo), or multi-cluster operations."]', '["kubernetes","timoni","cue","kluctl","fluxcd","gimlet","sveltos"]', 1759276800, '["rawkode"]', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"GitOps is more than a controller—you need packaging discipline, environment orchestration, reconciliation pipelines, and developer UX. This path assembles opinionated tools so platform engineers can scale fleets while keeping guardrails intact."}]},{"type":"heading","attrs":{"level":2,"id":"learning-objectives"},"content":[{"type":"text","text":"Learning Objectives"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Author type-safe application packages with CUE/Timoni and publish them as OCI artifacts."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Orchestrate multi-environment rollouts with Kluctl’s structural diffs and templating."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Bootstrap FluxCD 2, model sources/Kustomizations/HelmReleases, and control reconcilers with dependencies."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Provide a developer-facing GitOps workflow via Gimlet while preserving Git-based audit trails."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Manage add-ons across clusters using Sveltos’ intent-based policies and dynamic classifiers."}]}]}]},{"type":"heading","attrs":{"level":2,"id":"videos-in-this-path"},"content":[{"type":"text","text":"Videos in This Path"}]},{"type":"heading","attrs":{"level":3,"id":"1-timoni-cue-powered-package-management"},"content":[{"type":"text","text":"1. "},{"type":"text","text":"Timoni: CUE-powered Package Management","marks":[{"type":"link","attrs":{"href":"/watch/timoni-cue-powered-package-management-for-kubernetes","target":null,"rel":null,"class":null,"title":null}}]}]},{"type":"paragraph","content":[{"type":"text","text":"Why it matters:","marks":[{"type":"bold"}]},{"type":"text","text":" Configuration drift often starts with templating errors. Timoni couples CUE validation with OCI distribution so application definitions stay trustworthy."}]},{"type":"paragraph","content":[{"type":"text","text":"What you''ll learn:","marks":[{"type":"bold"}]}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Model services in CUE, enforce schemas, and catch mistakes before they hit the cluster."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Package modules/bundles and push them to OCI registries alongside container images."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Upgrade safely with server-side apply and observe minimal diffs."}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"Key takeaways:","marks":[{"type":"bold"}]}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Timoni replaces ad-hoc Helm templating with type-safe unification, reducing runtime surprises."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"OCI-backed bundles make promotion pipelines reproducible and auditable."}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"Hands-on drill:","marks":[{"type":"bold"}]},{"type":"text","text":" Convert an existing workload into a Timoni module + bundle, publish it to an OCI registry, and deploy it to staging."}]},{"type":"heading","attrs":{"level":3,"id":"2-hands-on-introduction-to-kluctl"},"content":[{"type":"text","text":"2. "},{"type":"text","text":"Hands-on Introduction to Kluctl","marks":[{"type":"link","attrs":{"href":"/watch/hands-on-introduction-to-kluctl","target":null,"rel":null,"class":null,"title":null}}]}]},{"type":"paragraph","content":[{"type":"text","text":"Why it matters:","marks":[{"type":"bold"}]},{"type":"text","text":" Once packages are solid, you need promotion discipline. Kluctl adds environment targets, previews, and pruning on top of GitOps."}]},{"type":"paragraph","content":[{"type":"text","text":"What you''ll learn:","marks":[{"type":"bold"}]}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Structure a Kluctl project with dev/stage/prod targets using Jinja2 and variable files."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Preview pending changes via "},{"type":"text","text":"kluctl diff","marks":[{"type":"code"}]},{"type":"text","text":" before committing to Git."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Sequence resource deployments and clean out abandoned objects with "},{"type":"text","text":"kluctl prune","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"Key takeaways:","marks":[{"type":"bold"}]}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Kluctl glues templating, diffs, and GitOps together so environments stay predictable."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Change previews provide guardrails missing from plain "},{"type":"text","text":"kubectl apply","marks":[{"type":"code"}]},{"type":"text","text":" or raw Git controllers."}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"Hands-on drill:","marks":[{"type":"bold"}]},{"type":"text","text":" Build a three-target Kluctl repo, run diff/deploy for each environment, and document a rollback flow."}]},{"type":"heading","attrs":{"level":3,"id":"3-gitops-tutorial-with-fluxcd-2-gitops-toolkit"},"content":[{"type":"text","text":"3. "},{"type":"text","text":"GitOps Tutorial with FluxCD 2 (GitOps Toolkit)","marks":[{"type":"link","attrs":{"href":"/watch/gitops-tutorial-with-fluxcd-2-gitops-toolkit","target":null,"rel":null,"class":null,"title":null}}]}]},{"type":"paragraph","content":[{"type":"text","text":"Why it matters:","marks":[{"type":"bold"}]},{"type":"text","text":" FluxCD is the reconciliation engine for your GitOps platform. Master its controllers, dependencies, and health checks."}]},{"type":"paragraph","content":[{"type":"text","text":"What you''ll learn:","marks":[{"type":"bold"}]}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Bootstrap FluxCD with "},{"type":"text","text":"gotk bootstrap","marks":[{"type":"code"}]},{"type":"text","text":" and connect it to a Git repo."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Define "},{"type":"text","text":"GitRepository","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"HelmRepository","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"Kustomization","marks":[{"type":"code"}]},{"type":"text","text":", and "},{"type":"text","text":"HelmRelease","marks":[{"type":"code"}]},{"type":"text","text":" resources."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Chain dependencies, enforce health checks, and suspend/resume reconciliation during incidents."}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"Key takeaways:","marks":[{"type":"bold"}]}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"FluxCD 2 decomposes GitOps into modular controllers—sources, kustomizations, Helm—so pipelines stay composable."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Dependency graphs and health gates ensure infrastructure comes up in the right order."}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"Hands-on drill:","marks":[{"type":"bold"}]},{"type":"text","text":" Bootstrap Flux into a test cluster, deploy an app with a HelmRelease, and add a dependency/health gate on a prerequisite component."}]},{"type":"heading","attrs":{"level":3,"id":"4-hands-on-introduction-to-gitops-with-gimlet"},"content":[{"type":"text","text":"4. "},{"type":"text","text":"Hands-on Introduction to GitOps with Gimlet","marks":[{"type":"link","attrs":{"href":"/watch/hands-on-introduction-to-gitops-with-gimlet","target":null,"rel":null,"class":null,"title":null}}]}]},{"type":"paragraph","content":[{"type":"text","text":"Why it matters:","marks":[{"type":"bold"}]},{"type":"text","text":" Developers need a polished workflow, not CRDs. Gimlet layers a UI and marketplace on top of Flux so teams ship without touching YAML."}]},{"type":"paragraph","content":[{"type":"text","text":"What you''ll learn:","marks":[{"type":"bold"}]}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Install Gimlet, connect it to a cluster, and trigger a buildpack-powered deploy."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Watch how Gimlet writes Git commits/PRs that Flux reconciles."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Manage configuration changes (replicas, env vars) and install add-ons from the marketplace."}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"Key takeaways:","marks":[{"type":"bold"}]}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Gimlet offers a stair-step journey into GitOps—UI onboarding backed by Git commits you can review."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Focused developer workflows keep platform teams in control while devs stay productive."}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"Hands-on drill:","marks":[{"type":"bold"}]},{"type":"text","text":" Deploy an app via Gimlet, approve the resulting Git PR, and exercise a rollback using Git history."}]},{"type":"heading","attrs":{"level":3,"id":"5-hands-on-tutorial-of-project-sveltos"},"content":[{"type":"text","text":"5. "},{"type":"text","text":"Hands-on Tutorial of Project Sveltos","marks":[{"type":"link","attrs":{"href":"/watch/hands-on-tutorial-of-project-sveltos","target":null,"rel":null,"class":null,"title":null}}]}]},{"type":"paragraph","content":[{"type":"text","text":"Why it matters:","marks":[{"type":"bold"}]},{"type":"text","text":" GitOps doesn’t stop at workloads. Sveltos pushes add-ons and policies across fleets based on intent and cluster metadata."}]},{"type":"paragraph","content":[{"type":"text","text":"What you''ll learn:","marks":[{"type":"bold"}]}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Target clusters with "},{"type":"text","text":"ClusterProfile","marks":[{"type":"code"}]},{"type":"text","text":" resources driven by labels, versions, or runtime state."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Automatically install add-ons as clusters register or change properties."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Integrate Sveltos with Flux so add-on definitions live in Git and reconcile continuously."}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"Key takeaways:","marks":[{"type":"bold"}]}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Sveltos eliminates per-cluster babysitting—classifiers apply the right configs as fleets evolve."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"GitOps integration keeps add-on state auditable and aligned with compliance requirements."}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"Hands-on drill:","marks":[{"type":"bold"}]},{"type":"text","text":" Label two clusters, create a ClusterProfile that deploys an ingress controller, and verify Sveltos heals manual drift."}]},{"type":"heading","attrs":{"level":2,"id":"bonus-practice"},"content":[{"type":"text","text":"Bonus Practice"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Kluctl Controller Deep Dive","marks":[{"type":"link","attrs":{"href":"/watch/kluctl-new-features-and-updates","target":null,"rel":null,"class":null,"title":null}}]},{"type":"text","text":" — manage GitOps natively via CRDs."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Feature Flags via GitOps with Flipt","marks":[{"type":"link","attrs":{"href":"/watch/feature-flags-via-gitops-with-flipt","target":null,"rel":null,"class":null,"title":null}}]},{"type":"text","text":" — extend GitOps workflows beyond infrastructure."}]}]}]},{"type":"heading","attrs":{"level":2,"id":"fleet-follow-ups"},"content":[{"type":"text","text":"Fleet Follow-ups"}]},{"type":"orderedList","attrs":{"start":1,"type":null},"content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Wire Timoni and Kluctl bundles into Flux via OCI sources + Kustomizations for full GitOps automation."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Onboard a pilot team to Gimlet, gather feedback, and codify approvals/rollbacks in Git workflows."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Combine Flux alerts + Sveltos reconciliation metrics to build fleet-level operational dashboards and policies."}]}]}]}]}', 1790105224000);
--> statement-breakpoint
INSERT INTO `learning_paths` (`id`, `title`, `description`, `difficulty`, `estimated_duration`, `prerequisites`, `technologies`, `published_at`, `authors`, `body`, `updated_at`) VALUES ('klustered-advanced-cluster-triage', 'Klustered: Advanced Cluster Triage', 'Master the craft of rescuing broken clusters. This path walks through real war‑room incidents so you can debug the control plane, container runtime, and host OS when kubectl alone is useless.', 'advanced', 447, '["Deep understanding of Kubernetes architecture (control plane, worker nodes, etcd, static pods).","Proficiency with kubectl, kubectl debug, and common triage commands (describe, logs, events).","Comfort administering Linux servers with systemd, journalctl, iptables, tc, and process tooling (ps, lsof).","Experience with container runtimes (containerd, CRI) and troubleshooting with crictl/ctr.","Familiarity with etcd administration (etcdctl, snapshots, compaction) and TLS fundamentals."]', '["kubernetes","containerd","etcd"]', 1759276800, '["rawkode"]', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Go beyond kubectl and develop a battle-tested methodology for diagnosing multi-layer outages. Each scenario highlights a different failure domain—nodes, networking, security, and host-level manipulation—so you can bring clusters back from the dead."}]},{"type":"heading","attrs":{"level":2,"id":"learning-objectives"},"content":[{"type":"text","text":"Learning Objectives"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Adopt a repeatable triage framework: validate symptoms, isolate the failing layer, and confirm the fix."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Combine Kubernetes logs with host forensics ("},{"type":"text","text":"journalctl","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"systemctl","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"ps","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"lsof","marks":[{"type":"code"}]},{"type":"text","text":") when the API server is lying—or gone."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Repair control-plane failures by dissecting static pod manifests, TLS assets, and etcd health."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Detect malicious persistence (cron/systemd jobs, "},{"type":"text","text":"ld.so.preload","marks":[{"type":"code"}]},{"type":"text","text":", kubeconfig auth plugins) that reintroduce problems after a reboot."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Harden clusters after recovery by applying network controls, auditing admission webhooks, and documenting runbooks."}]}]}]},{"type":"heading","attrs":{"level":2,"id":"videos-in-this-path"},"content":[{"type":"text","text":"Videos in This Path"}]},{"type":"heading","attrs":{"level":3,"id":"1-marino-wijay--john-anderson"},"content":[{"type":"text","text":"1. "},{"type":"text","text":"Marino Wijay & John Anderson","marks":[{"type":"link","attrs":{"href":"/watch/marino-wijay-and-john-anderson","target":null,"rel":null,"class":null,"title":null}}]}]},{"type":"paragraph","content":[{"type":"text","text":"Why it matters:","marks":[{"type":"bold"}]},{"type":"text","text":" Kubelet crashes and CNI misfires are the bread-and-butter incidents that escalate quickly. This episode establishes a systematic triage cadence."}]},{"type":"paragraph","content":[{"type":"text","text":"What you''ll learn:","marks":[{"type":"bold"}]}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Diagnose "},{"type":"text","text":"NodeNotReady","marks":[{"type":"code"}]},{"type":"text","text":" states by correlating kubelet logs, CNI status, and certificate errors."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Inspect static pod manifests and component arguments under "},{"type":"text","text":"/etc/kubernetes/manifests","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Track down webhook failures and broken admission controllers that silently reject workloads."}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"Key takeaways:","marks":[{"type":"bold"}]}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Trust but verify your cluster context and credentials before making changes."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Pod lifecycle issues often stem from lower layers—container runtime, CNI, or certificates—not the workload itself."}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"Hands-on drill:","marks":[{"type":"bold"}]},{"type":"text","text":" Reproduce a "},{"type":"text","text":"NodeNotReady","marks":[{"type":"code"}]},{"type":"text","text":" incident by breaking the CNI config in a test cluster, then repair it using the workflow demonstrated."}]},{"type":"heading","attrs":{"level":3,"id":"2-hans-kristian-flaatten--zach-wachtel"},"content":[{"type":"text","text":"2. "},{"type":"text","text":"Hans Kristian Flaatten & Zach Wachtel","marks":[{"type":"link","attrs":{"href":"/watch/hans-kristian-flaatten-and-zach-wachtel","target":null,"rel":null,"class":null,"title":null}}]}]},{"type":"paragraph","content":[{"type":"text","text":"Why it matters:","marks":[{"type":"bold"}]},{"type":"text","text":" Slow control planes are harder than outright failures. This session shows how to hunt down etcd pain, I/O throttling, and sneaky persistence."}]},{"type":"paragraph","content":[{"type":"text","text":"What you''ll learn:","marks":[{"type":"bold"}]}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Profile control-plane latency and leader-election behaviour when etcd is under duress."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Use low-level tools ("},{"type":"text","text":"crictl","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"journalctl","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"iostat","marks":[{"type":"code"}]},{"type":"text","text":") when "},{"type":"text","text":"kubectl","marks":[{"type":"code"}]},{"type":"text","text":" no longer returns data."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Discover malicious cron/systemd jobs reintroducing broken configs after each reboot."}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"Key takeaways:","marks":[{"type":"bold"}]}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"etcd health directly governs API responsiveness; treat disk I/O and quotas as first-class SLOs."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Persistent host tasks can undo your fixes—eradicate them or they’ll respawn the outage."}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"Hands-on drill:","marks":[{"type":"bold"}]},{"type":"text","text":" Simulate etcd I/O starvation (e.g., "},{"type":"text","text":"tc","marks":[{"type":"code"}]},{"type":"text","text":" or cgroup limits) and practice restoring health plus cleaning persistence hooks."}]},{"type":"heading","attrs":{"level":3,"id":"3-alex-jones--alistair-hey"},"content":[{"type":"text","text":"3. "},{"type":"text","text":"Alex Jones & Alistair Hey","marks":[{"type":"link","attrs":{"href":"/watch/alex-jones-and-alistair-hey","target":null,"rel":null,"class":null,"title":null}}]}]},{"type":"paragraph","content":[{"type":"text","text":"Why it matters:","marks":[{"type":"bold"}]},{"type":"text","text":" Networking mysteries rarely announce themselves. This duel demonstrates how to peel back NodePorts, policies, and host firewalls."}]},{"type":"paragraph","content":[{"type":"text","text":"What you''ll learn:","marks":[{"type":"bold"}]}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Trace traffic with "},{"type":"text","text":"kubectl exec","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"iptables -t nat","marks":[{"type":"code"}]},{"type":"text","text":", and "},{"type":"text","text":"tc","marks":[{"type":"code"}]},{"type":"text","text":" to find where packets die."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Validate kube-controller-manager and kubelet configs when scheduling subtly fails."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Guard yourself against sabotaged tooling (rogue aliases, modified kubeconfigs) that hinder troubleshooting."}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"Key takeaways:","marks":[{"type":"bold"}]}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Multi-layer debugging beats guesswork—test from pod → node → service to pinpoint the break."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Always confirm your tools haven’t been tampered with; even "},{"type":"text","text":"kubectl","marks":[{"type":"code"}]},{"type":"text","text":" can be weaponized."}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"Hands-on drill:","marks":[{"type":"bold"}]},{"type":"text","text":" Inject latency with "},{"type":"text","text":"tc qdisc","marks":[{"type":"code"}]},{"type":"text","text":", observe service behaviour, then revert settings and record a runbook entry."}]},{"type":"heading","attrs":{"level":3,"id":"4-the-community-vs-rawkode"},"content":[{"type":"text","text":"4. "},{"type":"text","text":"The Community vs. Rawkode","marks":[{"type":"link","attrs":{"href":"/watch/the-community-vs-rawkode","target":null,"rel":null,"class":null,"title":null}}]}]},{"type":"paragraph","content":[{"type":"text","text":"Why it matters:","marks":[{"type":"bold"}]},{"type":"text","text":" Security incidents often masquerade as outages. This group effort dissects a malicious kubeconfig helper and recovers the control plane."}]},{"type":"paragraph","content":[{"type":"text","text":"What you''ll learn:","marks":[{"type":"bold"}]}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Audit kubeconfig exec plugins to detect hostile authentication helpers."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Use classic Linux tooling ("},{"type":"text","text":"ps","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"at","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"env","marks":[{"type":"code"}]},{"type":"text","text":") to uncover suspicious activity on nodes."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Restore control-plane availability by editing static manifests and restarting kubelet safely."}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"Key takeaways:","marks":[{"type":"bold"}]}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"kubeconfig files are executable attack surfaces—treat them like code."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Static pod manifests provide single points of failure; secure and monitor them rigorously."}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"Hands-on drill:","marks":[{"type":"bold"}]},{"type":"text","text":" Craft a harmless kubeconfig exec helper, document how it executes, then disable it using RBAC and config policies."}]},{"type":"heading","attrs":{"level":3,"id":"5-klustered-11"},"content":[{"type":"text","text":"5. "},{"type":"text","text":"Klustered #11","marks":[{"type":"link","attrs":{"href":"/watch/klustered-11","target":null,"rel":null,"class":null,"title":null}}]}]},{"type":"paragraph","content":[{"type":"text","text":"Why it matters:","marks":[{"type":"bold"}]},{"type":"text","text":" The finale showcases deep Linux forensics—hidden processes, etcd DoS, and host firewalls—under extreme pressure."}]},{"type":"paragraph","content":[{"type":"text","text":"What you''ll learn:","marks":[{"type":"bold"}]}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Detect tampering techniques ("},{"type":"text","text":"ld.so.preload","marks":[{"type":"code"}]},{"type":"text","text":", rogue "},{"type":"text","text":"systemd","marks":[{"type":"code"}]},{"type":"text","text":" units) that hide processes and binaries."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Recover from etcd quota exhaustion and network lockouts using snapshots, compaction, and targeted iptables rules."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Combine filesystem, network, and process evidence into a cohesive incident timeline."}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"Key takeaways:","marks":[{"type":"bold"}]}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Complex outages demand patience, logs, and note-taking before touching anything."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Hardened control planes require both Kubernetes and OS-level defenses (firewalls, file integrity, RBAC)."}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"Hands-on drill:","marks":[{"type":"bold"}]},{"type":"text","text":" Build a lab where etcd hits its quota, practice compaction/defrag, then add iptables rules to lock down peer traffic."}]},{"type":"heading","attrs":{"level":2,"id":"bonus-practice-scenarios"},"content":[{"type":"text","text":"Bonus Practice Scenarios"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Jetstack & CrashLoopBackoff","marks":[{"type":"link","attrs":{"href":"/watch/jetstack-and-crashbeerbackoff","target":null,"rel":null,"class":null,"title":null}}]},{"type":"text","text":" — Chaos around admission webhooks and TLS."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"IBM & Nisum","marks":[{"type":"link","attrs":{"href":"/watch/ibm-and-nisum","target":null,"rel":null,"class":null,"title":null}}]},{"type":"text","text":" — Multi-team debugging of broken upgrades."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Klustered Teams: Aerospike & Pixie Labs","marks":[{"type":"link","attrs":{"href":"/watch/klustered-teams-aerospike-and-pixielabs","target":null,"rel":null,"class":null,"title":null}}]},{"type":"text","text":" — Service mesh vs. DNS whodunit."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Chainguard vs. Chainguard","marks":[{"type":"link","attrs":{"href":"/watch/klustered-teams-chainguard-vs-chainguard-2","target":null,"rel":null,"class":null,"title":null}}]},{"type":"text","text":" — Supply-chain sabotage meets cluster hardening."}]}]}]},{"type":"heading","attrs":{"level":2,"id":"after-action-suggestions"},"content":[{"type":"text","text":"After-Action Suggestions"}]},{"type":"orderedList","attrs":{"start":1,"type":null},"content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Turn your notes into a written incident response playbook (symptom → hypothesis → command sequence)."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Automate recurring diagnostics with "},{"type":"text","text":"kubectl debug","marks":[{"type":"code"}]},{"type":"text","text":" profiles or Systemd/Ansible scripts."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Feed lessons learned into platform guardrails: enforce admission webhook health, lock down kubeconfig exec plugins, and monitor etcd quotas continuously."}]}]}]}]}', 1790105224000);
